"""The handbook's index (docs/01, Appendix E) is generated by
tools/handbook_index.py from a curated term list. These tests keep it from
drifting: every term must still resolve to its definition, the committed
index must match a fresh build, and every link in it must land on a real
target (a heading's GitHub anchor or a placed index anchor)."""

import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))

import handbook_index as hi  # noqa: E402


def _book():
    with open(hi.BOOK, encoding="utf-8") as fh:
        return fh.read()


def test_every_term_resolves_and_the_index_is_current():
    text = _book()
    new, problems = hi.build(text)
    assert problems == [], problems
    assert new == text, "the index is stale; run python3 tools/handbook_index.py"


def test_every_index_link_lands_on_a_real_target():
    text = _book()
    lines = text.split("\n")
    scan = hi._scan(lines)
    targets = {s[2] for s in scan if s[2]}
    targets |= set(re.findall(r'<a id="(ix-[a-z0-9-]+)"></a>', text))
    index = text[text.index(hi.BEGIN):text.index(hi.END)]
    links = re.findall(r"\]\(#([^)]+)\)", index)
    assert links
    missing = [l for l in links if l not in targets]
    assert missing == [], missing


def test_the_slug_matches_the_hand_written_contents():
    # The contents list at the top was written by hand against GitHub's
    # rendering; the generator's anchors must agree with every one of them.
    text = _book()
    head = text[:text.index("## Chapter 1:")]
    for m in re.finditer(r"^- \[([^\]]+)\]\(#([^)]+)\)$", head, re.M):
        assert hi.slug(m.group(1)) == m.group(2), m.group(1)
